# ---------------------------------------------------------------------------
# Local runner: prepare once, support all dose controls, and health-gate outputs.
# ---------------------------------------------------------------------------
write(
    "scripts/run_local_mac_experiments.sh",
    '''#!/usr/bin/env bash\nset -euo pipefail\n\nif [ "$#" -lt 2 ] || [ "$#" -gt 4 ]; then\n  echo "usage: $0 DATA_ROOT RESULTS_ROOT [TOKEN_MULTIPLIER=20] [DEVICE=auto]" >&2\n  exit 2\nfi\n\nSCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"\nREPO_ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"\ncd "$REPO_ROOT"\n\nDATA_ROOT="$1"\nRESULTS_ROOT="$2"\nTOKEN_MULTIPLIER="${3:-20}"\nDEVICE="${4:-auto}"\nLEVELS="${WWGPT_LEVELS:-0,1,2}"\nSEEDS="${WWGPT_SEEDS:-1337,2027,4099}"\nOPTIMIZERS="${WWGPT_OPTIMIZERS:-adamw}"\nWWPGD_MODES="${WWGPT_WWPGD_MODES:-adaptive}"\nUNIFORM_HARDNESS="${WWGPT_UNIFORM_HARDNESS:-0.25}"\nTARGET_ALPHA="${WWGPT_TARGET_ALPHA:-2.0}"\nBLEND_ETA="${WWGPT_BLEND_ETA:-0.5}"\nCAYLEY_ETA="${WWGPT_CAYLEY_ETA:-0.25}"\nMAX_PER_STEP_GAIN="${WWGPT_MAX_PER_STEP_GAIN:-0.02}"\nMAX_ENDPOINT_FRACTION="${WWGPT_MAX_ENDPOINT_FRACTION:-0.40}"\nCUMULATIVE_DOSE_CAP="${WWGPT_CUMULATIVE_DOSE_CAP:-0.025}"\nPER_STEP_RELATIVE_CAP="${WWGPT_PER_STEP_RELATIVE_CAP:-0.001}"\nLAYER_LR="${WWGPT_LAYER_LR:-flat}"\nLR_SCHEDULE="${WWGPT_LR_SCHEDULE:-warmup_cosine}"\nLR_SCALE_RULE="${WWGPT_LR_SCALE_RULE:-fixed}"\nLR_REFERENCE_TOKENS="${WWGPT_LR_REFERENCE_TOKENS:-4096}"\nCANDIDATE_DEVICE="${WWGPT_CANDIDATE_DEVICE:-auto}"\nRESUME="${WWGPT_RESUME:-1}"\nRUN_NOTEBOOKS="${WWGPT_RUN_NOTEBOOKS:-1}"\nANALYSIS_PLAN="${WWGPT_ANALYSIS_PLAN:-configs/analysis_plan_exploratory.yaml}"\n\nmkdir -p "$RESULTS_ROOT"\nwwgpt local-readiness \\\n  --device "$DEVICE" --levels "$LEVELS" --optimizers "$OPTIMIZERS" \\\n  --output "$RESULTS_ROOT/local-readiness"\n\nIFS=',' read -r -a LEVEL_ARRAY <<< "$LEVELS"\nIFS=',' read -r -a OPTIMIZER_ARRAY <<< "$OPTIMIZERS"\nIFS=',' read -r -a MODE_ARRAY <<< "$WWPGD_MODES"\n\n# Prepare/reuse each immutable data identity exactly once.\nfor LEVEL in "${LEVEL_ARRAY[@]}"; do\n  CONFIG="configs/level${LEVEL}_adaptive_alpha.yaml"\n  echo "[local-mac] ensure data level=$LEVEL" >&2\n  wwgpt prepare-data \\\n    --level "$LEVEL" --config "$CONFIG" --data-root "$DATA_ROOT" \\\n    --token-multiplier "$TOKEN_MULTIPLIER"\ndone\n\nfor MODE in "${MODE_ARRAY[@]}"; do\n  if [ "$MODE" = "adaptive" ]; then\n    MODE_ARGS=(--wwpgd-adaptive-mode alpha_distance)\n  elif [ "$MODE" = "uniform" ]; then\n    MODE_ARGS=(\n      --wwpgd-adaptive-mode uniform\n      --wwpgd-alpha-max-hardness "$UNIFORM_HARDNESS"\n    )\n  else\n    echo "unknown WWPGD mode: $MODE (expected adaptive or uniform)" >&2\n    exit 2\n  fi\n  for OPTIMIZER in "${OPTIMIZER_ARRAY[@]}"; do\n    VARIANT_ROOT="$RESULTS_ROOT/${MODE}/${OPTIMIZER}/${LAYER_LR}/${LR_SCALE_RULE}"\n    mkdir -p "$VARIANT_ROOT"\n    for LEVEL in "${LEVEL_ARRAY[@]}"; do\n      CONFIG="configs/level${LEVEL}_adaptive_alpha.yaml"\n      COMMON=(\n        --level "$LEVEL" --config "$CONFIG" --analysis-plan "$ANALYSIS_PLAN"\n        --data-root "$DATA_ROOT" --results-root "$VARIANT_ROOT"\n        --token-multiplier "$TOKEN_MULTIPLIER" --seeds "$SEEDS"\n        --optimizer "$OPTIMIZER" --extensions none,wwpgd --device "$DEVICE"\n        --layer-lr "$LAYER_LR" --lr-schedule "$LR_SCHEDULE"\n        --lr-scale-rule "$LR_SCALE_RULE"\n        --lr-reference-tokens-per-step "$LR_REFERENCE_TOKENS"\n        --target-alpha "$TARGET_ALPHA"\n        --wwpgd-blend-eta "$BLEND_ETA"\n        --wwpgd-cayley-eta "$CAYLEY_ETA"\n        --wwpgd-max-per-step-gain "$MAX_PER_STEP_GAIN"\n        --wwpgd-max-endpoint-fraction-per-refresh "$MAX_ENDPOINT_FRACTION"\n        --wwpgd-max-cumulative-relative-change-per-refresh "$CUMULATIVE_DOSE_CAP"\n        --wwpgd-per-step-max-relative-change "$PER_STEP_RELATIVE_CAP"\n        --wwpgd-candidate-device "$CANDIDATE_DEVICE"\n        "${MODE_ARGS[@]}"\n      )\n      wwgpt run-multiseed "${COMMON[@]}" --dry-run \\\n        > "$VARIANT_ROOT/level${LEVEL}_resolved_execution.txt"\n      if [ "$RESUME" = "1" ]; then\n        COMMON+=(--resume)\n      fi\n      wwgpt run-multiseed "${COMMON[@]}"\n    done\n    wwgpt check-health --experiment-root "$VARIANT_ROOT"\n    wwgpt analyze-results "$VARIANT_ROOT" --analysis-plan "$ANALYSIS_PLAN"\n    python -m wwgpt.cross_level_analysis \\\n      --results-root "$VARIANT_ROOT" \\\n      --output-dir "$VARIANT_ROOT/cross_level_analysis" \\\n      --figures-dir "$VARIANT_ROOT/cross_level_analysis/figures"\n    if [ "$RUN_NOTEBOOKS" = "1" ]; then\n      export WWGPT_RESULTS_ROOT="$VARIANT_ROOT"\n      export WWGPT_NOTEBOOK_OUTPUT_DIR="$VARIANT_ROOT/notebook-analysis"\n      export WWGPT_ANALYSIS_PLAN="$ANALYSIS_PLAN"\n      export WWGPT_BASE_OPTIMIZER="$OPTIMIZER"\n      export WWGPT_LEVEL=""\n      export WWGPT_TOKEN_MULTIPLIER="$TOKEN_MULTIPLIER"\n      export WWGPT_NOTEBOOK_STRICT=1\n      ./scripts/run_analysis_notebooks.sh\n    fi\n  done\ndone\n\necho "[local-mac] complete: $RESULTS_ROOT" >&2\n''',
    executable=True,
)

# ---------------------------------------------------------------------------
# Health and workflow regression tests.
# ---------------------------------------------------------------------------
write(
    "tests/test_run_health_and_reuse.py",
    '''from __future__ import annotations\n\nimport hashlib\nimport json\nfrom pathlib import Path\n\nimport pandas as pd\nimport pytest\n\nfrom wwgpt.config import ModelConfig, TrainConfig\nfrom wwgpt.data import required_evaluation_tokens\nfrom wwgpt.run_health import generate_experiment_health, generate_run_health\n\n\ndef _write_json(path: Path, value: dict) -> None:\n    path.write_text(json.dumps(value))\n\n\ndef _valid_run(tmp_path: Path, extension: str = "none") -> Path:\n    run = tmp_path / "pair_1337" / ("adamw_wwpgd" if extension == "wwpgd" else "adamw") / "run_1"\n    checkpoints = run / "checkpoints"\n    checkpoints.mkdir(parents=True)\n    checkpoint = checkpoints / "best.pt"\n    checkpoint.write_bytes(b"checkpoint")\n    digest = hashlib.sha256(checkpoint.read_bytes()).hexdigest()\n    _write_json(\n        run / "manifest.json",\n        {\n            "valid_for_science": True, "scientific_schema_version": 3,\n            "arm_name": "adamw_wwpgd" if extension == "wwpgd" else "adamw",\n            "base_optimizer": "adamw", "extension": extension, "seed": 1337,\n            "level": 0, "token_multiplier": 20,\n            "optimizer_hyperparameters": {"eval_batches": 1, "batch_size": 1},\n            "model_config": {"block_size": 4},\n            "wwpgd_installed_version": "0.1", "wwpgd_commit": "runtime",\n        },\n    )\n    _write_json(\n        run / "run_complete.json",\n        {"step": 1, "wwpgd_call_count": 0, "stock_wwpgd_invocation_count": 0},\n    )\n    _write_json(\n        run / "data_manifest.json",\n        {"validation_tokens": 100, "test_tokens": 100},\n    )\n    selected = {\n        "train_loss": 2.0, "train_perplexity": 7.0, "train_accuracy": 0.2,\n        "validation_loss": 2.1, "validation_perplexity": 8.0, "validation_accuracy": 0.19,\n        "test_loss": 2.2, "test_perplexity": 9.0, "test_accuracy": 0.18,\n        "checkpoint_path": str(checkpoint), "checkpoint_hash": digest,\n        "selection_metric": "validation_loss",\n    }\n    _write_json(run / "selected_checkpoint_metrics.json", selected)\n    pd.DataFrame(\n        [{\n            "evaluation_index": 0, "step": 1, "train_loss": 2.0,\n            "validation_loss": 2.1, "gradient_norm_before_clip": 1.0,\n            "gradient_norm_after_clip": 1.0, "model_parameter_l2_norm": 3.0,\n            "eligible_matrix_l2_norm": 2.0, "model_max_abs_parameter": 0.5,\n            "model_nonfinite_parameter_count": 0,\n            "gradient_nonfinite_element_count_before_clip": 0,\n            "total_elapsed_seconds": 1.0,\n        }]\n    ).to_csv(run / "metrics.csv", index=False)\n    pd.DataFrame(\n        [{\n            "optimizer_step": 1, "layer_name": "blocks.0.attn.key",\n            "alpha": 2.5, "valid_for_science": True, "projected": True,\n            "included_in_projected_alpha_summary": True,\n        }]\n    ).to_csv(run / "alpha_measurements.csv", index=False)\n    pd.DataFrame([{"step": 1, "trap_layer_fraction": 0.0}]).to_csv(\n        run / "weightwatcher_aggregates.csv", index=False\n    )\n    return run\n\n\ndef test_required_evaluation_tokens_matches_fixed_probe() -> None:\n    class Cfg:\n        train = TrainConfig(batch_size=2, eval_batches=3)\n        model = ModelConfig(block_size=4)\n    assert required_evaluation_tokens(Cfg()) == 25\n\n\ndef test_run_health_writes_machine_readable_artifacts(tmp_path: Path) -> None:\n    run = _valid_run(tmp_path)\n    report = generate_run_health(run)\n    assert report["ready_for_analysis"] is True\n    assert (run / "run_health.json").is_file()\n    assert (run / "run_health.csv").is_file()\n\n\ndef test_run_health_rejects_nonfinite_metrics(tmp_path: Path) -> None:\n    run = _valid_run(tmp_path)\n    frame = pd.read_csv(run / "metrics.csv")\n    frame.loc[0, "validation_loss"] = float("nan")\n    frame.to_csv(run / "metrics.csv", index=False)\n    report = generate_run_health(run)\n    assert report["ready_for_analysis"] is False\n    assert any(row["check"] == "finite_metrics" for row in report["findings"])\n\n\ndef test_experiment_health_aggregates_runs(tmp_path: Path) -> None:\n    _valid_run(tmp_path)\n    report = generate_experiment_health(tmp_path)\n    assert report["run_count"] == 1\n    assert report["ready_for_analysis"] is True\n    assert (tmp_path / "analysis" / "run_health_summary.csv").is_file()\n\n\ndef test_local_runner_prepares_before_optimizer_loop() -> None:\n    text = Path("scripts/run_local_mac_experiments.sh").read_text()\n    preparation = text.index('# Prepare/reuse each immutable data identity exactly once.')\n    mode_loop = text.index('for MODE in')\n    assert preparation < mode_loop\n    assert 'wwgpt check-health' in text\n    assert '--wwpgd-max-endpoint-fraction-per-refresh' in text\n    assert '--wwpgd-candidate-device' in text\n''',
)

print("Applied phase-two health and workflow changes")
